package com.github.bensrepository.raidrandomizer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RaidRandomizerPlugin.class);
		RuneLite.main(args);
	}
}

package com.github.bensrepository.raidrandomizer;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ChatIconManager;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;

@Slf4j
@Singleton
public class RaidIconManager
{
    @Inject
    private ChatIconManager chatIconManager;

    @Getter
    private int coxIconId;

    @Getter
    private int tobIconId;

    @Getter
    private int toaIconId;

    public void load()
    {
        try
        {
            log.info("Loading raid icons...");

            coxIconId = register("cox.png");
            tobIconId = register("tob.png");
            toaIconId = register("toa.png");

            log.info("Registered icons -> COX={}, TOB={}, TOA={}", coxIconId, tobIconId, toaIconId);
        }
        catch (Exception e)
        {
            log.error("Failed to load raid icons", e);
        }
    }

    private int register(String fileName)
    {
        BufferedImage image = loadImage(fileName);

        if (image == null)
        {
            log.error("Image load returned null for {}", fileName);
            return -1;
        }

        int id = chatIconManager.registerChatIcon(image);

        log.debug("Registered chat icon {} with id {}", fileName, id);

        return id;
    }

    private BufferedImage loadImage(String fileName)
    {
        try (InputStream stream = RaidIconManager.class.getResourceAsStream("/" + fileName))
        {
            if (stream == null)
            {
                log.error("Resource not found: {}", fileName);
                return null;
            }

            return ImageIO.read(stream);
        }
        catch (IOException e)
        {
            log.error("Error loading image {}", fileName, e);
            return null;
        }
    }

    public int getCoxChatIndex()
    {
        return chatIconManager.chatIconIndex(coxIconId);
    }

    public int getTobChatIndex()
    {
        return chatIconManager.chatIconIndex(tobIconId);
    }

    public int getToaChatIndex()
    {
        return chatIconManager.chatIconIndex(toaIconId);
    }
}

package com.github.bensrepository.raidrandomizer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("raidrandomizer")
public interface RaidRandomizerConfig extends Config
{
	@ConfigItem(
			keyName = "enableCox",
			name = "Chambers of Xeric",
			description = "Adds Chambers of Xeric to results.",
			position = 0
	)
	default boolean enableCox() { return true; }

	@ConfigItem(
			keyName = "enableTob",
			name = "Theatre of Blood",
			description = "Adds Theatre of Blood to results.",
			position = 1
	)
	default boolean enableTob() { return true; }

	@ConfigItem(
			keyName = "enableToa",
			name = "Tombs of Amascut",
			description = "Adds Tombs of Amascut to results.",
			position = 2
	)
	default boolean enableToa() { return true; }


	@ConfigItem(
			keyName = "useUtcSync",
			name = "Sync results",
			description = "Shows same result for all players with the plugin (all raids enabled)",
			position = 3
	)
	default boolean useUtcSync()
	{
		return true;
	}


	enum SpinSpeed
	{
		FAST,
		MEDIUM,
		SLOW
	}

	@ConfigItem(
			keyName = "spinSpeed",
			name = "Spin speed",
			description = "Roulette speed",
			position = 4
	)
	default SpinSpeed spinSpeed()
	{
		return SpinSpeed.MEDIUM;
	}


	@ConfigItem(
			keyName = "enableSounds",
			name = "Enable sounds",
			description = "Play drum and reveal sounds",
			position = 5
	)
	default boolean enableSounds()
	{
		return true;
	}
}

package com.github.bensrepository.raidrandomizer;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Slf4j
@PluginDescriptor(
		name = "Raid Randomizer",
		description = "Randomize the next raid you and your friends take on.",
		tags = {"raid", "randomizer", "utility"}
)
public class RaidRandomizerPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ScheduledExecutorService executor;
	@Inject private RaidRandomizerConfig config;
	@Inject private RaidIconManager raidIconManager;

	@Override
	protected void startUp() throws Exception
	{
		clientThread.invokeLater(() -> raidIconManager.load());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> raidIconManager.load());
		}
	}


	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();

		if (type != ChatMessageType.PUBLICCHAT &&
				type != ChatMessageType.CLAN_CHAT &&
				type != ChatMessageType.FRIENDSCHAT &&
				type != ChatMessageType.PRIVATECHAT &&
				type != ChatMessageType.PRIVATECHATOUT)
		{
			return;
		}

		if (!"!raid".equalsIgnoreCase(event.getMessage()))
			return;

		MessageNode node = event.getMessageNode();
		List<String> available = getAvailableRaids();

		if (available.isEmpty())
		{
			node.setRuneLiteFormatMessage("<col=ffffff>No raids enabled</col>");
			client.refreshChat();
			return;
		}

		// Capture seed for this spin
		long seed = config.useUtcSync()
				? getUtcEpoch() / 10      // 10-second deterministic bucket
				: System.nanoTime();     // true random seed

		int totalSpins = 28;
		long accumulatedDelay = 0;

		for (int i = 0; i < totalSpins; i++)
		{
			int base = config.spinSpeed() == RaidRandomizerConfig.SpinSpeed.FAST ? 5
					: config.spinSpeed() == RaidRandomizerConfig.SpinSpeed.SLOW ? 70
					: 35;

			double progress = (double) i / totalSpins;
			long delayStep = (long) (base + (progress * base * 3));

			accumulatedDelay += delayStep;

			int index = i;
			long scheduledTime = accumulatedDelay;

			executor.schedule(() ->
							clientThread.invoke(() ->
							{
								String name = available.get(index % available.size());

								node.setRuneLiteFormatMessage(
										"<col=ffff00>🎰 " + name + "</col>"
								);
								client.refreshChat();

								if (config.enableSounds())
								{
									client.playSoundEffect(227);
								}
							}),
					scheduledTime,
					TimeUnit.MILLISECONDS
			);
		}

		// Near miss
		accumulatedDelay += 300;
		executor.schedule(() ->
						clientThread.invoke(() ->
						{
							node.setRuneLiteFormatMessage(
									"<col=ff0000>🎰 " + available.get(0) + "</col>"
							);
							client.refreshChat();
						}),
				accumulatedDelay,
				TimeUnit.MILLISECONDS
		);

		// Final reveal
		accumulatedDelay += 600;
		executor.schedule(() ->
						clientThread.invoke(() ->
						{
							String result = rollRaid(seed);

							if (config.enableSounds())
							{
								client.playSoundEffect(199);
							}

							node.setRuneLiteFormatMessage("<col=00ff00>" + result + "</col>");
							client.refreshChat();
						}),
				accumulatedDelay,
				TimeUnit.MILLISECONDS
		);
	}

	private List<String> getAvailableRaids()
	{
		List<String> list = new ArrayList<>();

		if (config.useUtcSync())
		{
			// Sync mode always includes all raids
			list.add("Chambers of Xeric");
			list.add("Theatre of Blood");
			list.add("Tombs of Amascut");
		}
		else
		{
			if (config.enableCox()) list.add("Chambers of Xeric");
			if (config.enableTob()) list.add("Theatre of Blood");
			if (config.enableToa()) list.add("Tombs of Amascut");
		}

		return list;
	}

	private long getUtcEpoch()
	{
		return Instant.now().getEpochSecond();
	}

	private String rollRaid(long seed)
	{
		List<String> pool = config.useUtcSync()
				? Arrays.asList(
				"Chambers of Xeric",
				"Theatre of Blood",
				"Tombs of Amascut")
				: getAvailableRaids();

		if (pool.isEmpty())
		{
			return "<col=ffffff>No raids enabled</col>";
		}

		Random random = new Random(seed);
		String selected = pool.get(random.nextInt(pool.size()));

		switch (selected)
		{
			case "Chambers of Xeric":
				return "<img=" + raidIconManager.getCoxChatIndex() + "> <col=00ff00>Chambers of Xeric</col>";

			case "Theatre of Blood":
				return "<img=" + raidIconManager.getTobChatIndex() + "> <col=ff0000>Theatre of Blood</col>";

			default:
				return "<img=" + raidIconManager.getToaChatIndex() + "> <col=cc6600>Tombs of Amascut</col>";
		}
	}

	@Provides
	RaidRandomizerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RaidRandomizerConfig.class);
	}
}
